const {
  redisClient,
  CHANNELS,
  redisChannelManager,
  FLOWS_REGISTERY_TYPES
} = require('node-red/utils/redis');
const { log } = require("@node-red/util");

let _runtimeAPI;

function registerInternalAppRoutes() {
  _runtimeAPI.httpInternalApp.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok' });
  });
  _runtimeAPI.httpInternalApp.post('/apps/:appId/actions', async (req, res) => {
    const { appId } = req.params;
    const { tenantConfigId, action } = req.body;

    try {
      switch (action) {
        case FLOWS_REGISTERY_TYPES.REGISTER:
          await redisChannelManager.publish(
            CHANNELS.FLOW_REGISTERY,
            {
              appId,
              tenantConfigId,
              type: FLOWS_REGISTERY_TYPES.REGISTER
            }
          );
          break;
        case FLOWS_REGISTERY_TYPES.UNREGISTER:
          await redisChannelManager.publish(
            CHANNELS.FLOW_REGISTERY,
            {
              appId,
              tenantConfigId,
              type: FLOWS_REGISTERY_TYPES.UNREGISTER
            }
          );
          break;
        case FLOWS_REGISTERY_TYPES.DELETE:
          await redisChannelManager.publish(
            CHANNELS.FLOW_REGISTERY,
            {
              appId,
              tenantConfigId,
              type: FLOWS_REGISTERY_TYPES.DELETE
            }
          );
          break;
        default:
          return res
            .status(400)
            .json({ success: false, message: 'Invalid event type' });
      }
    } catch (error) {
      log.error("Error occured while publishing event action: " + action);
      return res.status(500).json({
        success: false,
        message: 'Internal server error ',
        error: error.message
      });
    }
    return res.status(200).json({ success: true });
  });
}

module.exports = {
  init: function (runtimeAPI) {
    _runtimeAPI = runtimeAPI;
    registerInternalAppRoutes();
  },
}
